package controlplane

import (
	"bytes"
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"os"
	"reflect"
	"testing"
	"time"
)

// testdata/test-vectors.json is synced verbatim from the control-plane repository
// (t3code-control-plane/protocol/test-vectors.json, generated by `npm run vectors`). Do not edit
// it by hand; re-copy it when the protocol changes.
type testVectors struct {
	ProtocolVersion   int    `json:"protocolVersion"`
	CodeAlphabet      string `json:"codeAlphabet"`
	CodeNormalization []struct {
		Input      string  `json:"input"`
		Normalized *string `json:"normalized"`
	} `json:"codeNormalization"`
	CodeFormatting []struct {
		Normalized string `json:"normalized"`
		Display    string `json:"display"`
	} `json:"codeFormatting"`
	Fingerprint struct {
		PublicKey   string `json:"publicKey"`
		Fingerprint string `json:"fingerprint"`
	} `json:"fingerprint"`
	PairingExchange struct {
		DeviceSeed string `json:"deviceSeed"`
		PublicKey  string `json:"publicKey"`
		Code       string `json:"code"`
		PairingID  string `json:"pairingId"`
		Timestamp  string `json:"timestamp"`
		Message    string `json:"message"`
		Signature  string `json:"signature"`
	} `json:"pairingExchange"`
	ConnectTokens struct {
		SigningKey struct {
			Seed string `json:"seed"`
			Kid  string `json:"kid"`
		} `json:"signingKey"`
		JWKS    JWKS `json:"jwks"`
		Context struct {
			Issuer          string `json:"issuer"`
			DeviceID        string `json:"deviceId"`
			RevocationEpoch int64  `json:"revocationEpoch"`
			Now             int64  `json:"now"`
		} `json:"context"`
		LeewaySeconds      int `json:"leewaySeconds"`
		MaxLifetimeSeconds int `json:"maxLifetimeSeconds"`
		Cases              []struct {
			Name          string `json:"name"`
			Token         string `json:"token"`
			RequiredScope Scope  `json:"requiredScope"`
			Revoked       bool   `json:"revoked"`
			Expect        struct {
				Valid  bool     `json:"valid"`
				Scopes []string `json:"scopes"`
				Error  string   `json:"error"`
			} `json:"expect"`
		} `json:"cases"`
	} `json:"connectTokens"`
	ToolScopes struct {
		Read  []string `json:"read"`
		Write []string `json:"write"`
	} `json:"toolScopes"`
}

func loadVectors(t *testing.T) *testVectors {
	t.Helper()
	data, err := os.ReadFile("testdata/test-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v testVectors
	if err := json.Unmarshal(data, &v); err != nil {
		t.Fatal(err)
	}
	return &v
}

func mustB64(t *testing.T, s string) []byte {
	t.Helper()
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		t.Fatalf("decode %q: %v", s, err)
	}
	return b
}

func TestVectorConstants(t *testing.T) {
	v := loadVectors(t)
	if v.ProtocolVersion != ProtocolVersion {
		t.Fatalf("protocolVersion = %d", v.ProtocolVersion)
	}
	if v.CodeAlphabet != CodeAlphabet {
		t.Fatalf("codeAlphabet = %q", v.CodeAlphabet)
	}
	if v.ConnectTokens.LeewaySeconds != VerifyLeewaySeconds || v.ConnectTokens.MaxLifetimeSeconds != MaxConnectTokenLifetime {
		t.Fatalf("leeway/lifetime mismatch: %d/%d", v.ConnectTokens.LeewaySeconds, v.ConnectTokens.MaxLifetimeSeconds)
	}
	if !reflect.DeepEqual(v.ToolScopes.Read, ReadTools) || !reflect.DeepEqual(v.ToolScopes.Write, WriteTools) {
		t.Fatalf("tool scopes mismatch: %+v", v.ToolScopes)
	}
	for _, tool := range v.ToolScopes.Read {
		if ScopeForTool(tool) != ScopeRead {
			t.Errorf("ScopeForTool(%q) != read", tool)
		}
	}
	for _, tool := range v.ToolScopes.Write {
		if ScopeForTool(tool) != ScopeWrite {
			t.Errorf("ScopeForTool(%q) != write", tool)
		}
	}
}

func TestVectorCodeNormalization(t *testing.T) {
	v := loadVectors(t)
	if len(v.CodeNormalization) == 0 {
		t.Fatal("no vectors")
	}
	for _, c := range v.CodeNormalization {
		got, ok := NormalizeUserCode(c.Input)
		if c.Normalized == nil {
			if ok {
				t.Errorf("NormalizeUserCode(%q) = %q, want invalid", c.Input, got)
			}
			continue
		}
		if !ok || got != *c.Normalized {
			t.Errorf("NormalizeUserCode(%q) = %q,%v want %q", c.Input, got, ok, *c.Normalized)
		}
	}
	for _, c := range v.CodeFormatting {
		if got := FormatUserCode(c.Normalized); got != c.Display {
			t.Errorf("FormatUserCode(%q) = %q want %q", c.Normalized, got, c.Display)
		}
	}
}

func TestVectorFingerprint(t *testing.T) {
	v := loadVectors(t)
	got, err := PublicKeyFingerprint(v.Fingerprint.PublicKey)
	if err != nil {
		t.Fatal(err)
	}
	if got != v.Fingerprint.Fingerprint {
		t.Fatalf("fingerprint = %q want %q", got, v.Fingerprint.Fingerprint)
	}
}

func TestVectorPairingExchange(t *testing.T) {
	v := loadVectors(t).PairingExchange
	id, err := DeviceIdentityFromSeed(mustB64(t, v.DeviceSeed))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(id.PublicKey(), mustB64(t, v.PublicKey)) || id.PublicKeyBase64() != v.PublicKey {
		t.Fatalf("public key = %s want %s", id.PublicKeyBase64(), v.PublicKey)
	}
	msg := PairingExchangeMessage(v.Code, v.PairingID, v.Timestamp)
	if msg != v.Message {
		t.Fatalf("message = %q want %q", msg, v.Message)
	}
	sig, err := id.SignPairingExchange(FormatUserCode(v.Code), v.PairingID, v.Timestamp)
	if err != nil {
		t.Fatal(err)
	}
	if sig != v.Signature {
		t.Fatalf("signature = %s want %s", sig, v.Signature)
	}
	if !bytes.Equal(mustB64(t, sig), mustB64(t, v.Signature)) {
		t.Fatal("signature bytes differ")
	}
	if !ed25519.Verify(id.PublicKey(), []byte(v.Message), mustB64(t, v.Signature)) {
		t.Fatal("vector signature does not verify")
	}
}

func TestVectorSigningKeyMatchesJWKS(t *testing.T) {
	ct := loadVectors(t).ConnectTokens
	priv := ed25519.NewKeyFromSeed(mustB64(t, ct.SigningKey.Seed))
	x := base64.RawURLEncoding.EncodeToString(priv.Public().(ed25519.PublicKey))
	if len(ct.JWKS.Keys) != 1 || ct.JWKS.Keys[0].X != x || ct.JWKS.Keys[0].Kid != ct.SigningKey.Kid {
		t.Fatalf("jwks does not match signing key: %+v", ct.JWKS)
	}
	if got := JWKThumbprint(x); got != ct.SigningKey.Kid {
		t.Fatalf("thumbprint = %s want %s", got, ct.SigningKey.Kid)
	}
}

func TestVectorConnectTokens(t *testing.T) {
	ct := loadVectors(t).ConnectTokens
	if len(ct.Cases) == 0 {
		t.Fatal("no cases")
	}
	for _, c := range ct.Cases {
		t.Run(c.Name, func(t *testing.T) {
			ctx := VerificationContext{
				Issuer:          ct.Context.Issuer,
				DeviceID:        ct.Context.DeviceID,
				RevocationEpoch: ct.Context.RevocationEpoch,
				Revoked:         c.Revoked,
				JWKS:            ct.JWKS,
				Now:             time.Unix(ct.Context.Now, 0),
			}
			claims, err := VerifyConnectToken(c.Token, ctx, c.RequiredScope)
			if c.Expect.Valid {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				if !reflect.DeepEqual(claims.Scopes, c.Expect.Scopes) {
					t.Fatalf("scopes = %v want %v", claims.Scopes, c.Expect.Scopes)
				}
				if claims.Audience != ct.Context.DeviceID || claims.Issuer != ct.Context.Issuer {
					t.Fatalf("claims = %+v", claims)
				}
				return
			}
			if err == nil {
				t.Fatalf("expected %s, got valid claims %+v", c.Expect.Error, claims)
			}
			verr, ok := err.(*VerifyError)
			if !ok {
				t.Fatalf("error type %T", err)
			}
			if string(verr.Code) != c.Expect.Error {
				t.Fatalf("code = %s (%s) want %s", verr.Code, verr.Reason, c.Expect.Error)
			}
		})
	}
}
